import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def remove_opt(values, k):
    if not values: return None
    head = N(values[0])
    cur = head
    for v in values[1:]:
        cur.nxt = N(v); cur = cur.nxt
    fast = head
    for _ in range(k):
        fast = fast.nxt
    if not fast:
        return head.nxt
    slow = head
    while fast.nxt:
        slow = slow.nxt
        fast = fast.nxt
    slow.nxt = slow.nxt.nxt
    return head

def to_list(head):
    out = []
    cur = head
    while cur:
        out.append(cur.v); cur = cur.nxt
    return out

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    vals = list(map(int, data[1:1 + n]))
    k = int(data[1 + n])
    print(' '.join(map(str, to_list(remove_opt(vals, k)))))
